template<class T>std::optional<T> mixed_row(const std::vector<T>& values,unsigned slot){const auto found=std::find_if(values.begin(),values.end(),[&](const auto& value){return value.slot==slot;});return found==values.end()?std::nullopt:std::optional(*found);}
void moved_instance(const MixedRepo::Snapshot& before,const MixedRepo::Snapshot& after,unsigned source,unsigned destination){
    const auto old_armor=mixed_row(before.base.armor,source),new_armor=mixed_row(after.base.armor,destination);if(old_armor){auto expected=*old_armor;expected.slot=static_cast<std::uint16_t>(destination);expected.revision=before.base.vault[destination].revision+1;require(new_armor&&*new_armor==expected,"Mixed lost complete armor source/provenance20");}else require(!new_armor,"Mixed invented armor overlay");
    const auto old_foreign=mixed_row(before.foreign,source),new_foreign=mixed_row(after.foreign,destination);if(old_foreign){auto expected=*old_foreign;expected.slot=static_cast<std::uint16_t>(destination);expected.revision=before.base.vault[destination].revision+1;require(new_foreign&&*new_foreign==expected,"Mixed lost complete foreign pins/source/parsed20");}else require(!new_foreign,"Mixed invented foreign overlay");
}
